'use client';

import { useState, useEffect } from 'react';
import CandleStickChart from '@/components/CandleStickChart/CandleStickChart';
import { CandlestickItem } from '@/types/candlestick';

export default function CandlestickPage() {
  const [chartData, setChartData] = useState<CandlestickItem[]>([]);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    const fetchCandlestickData = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/candlestick');
        if (!response.ok) throw new Error('Không thể tải dữ liệu nến');
        
        const data: CandlestickItem[] = await response.json();
        setChartData(data);
      } catch (error) {
        console.error('Lỗi kết nối API:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchCandlestickData();
  }, []);

  return (
    <main className="max-w-4xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-4">📈 Biểu Đồ Nến (Candlestick Chart)</h1>

      {loading ? (
        <p className="text-center py-8">Đang tải dữ liệu biểu đồ...</p>
      ) : (
        <CandleStickChart 
          data={chartData} 
          title="Tỷ giá VN-Index / Crypto" 
          height={400} 
        />
      )}
    </main>
  );
}